package com.myaaptha.domain.finance;
import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.fasterxml.jackson.databind.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class FinanceStatementsTest{
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;
 String member()throws Exception{String name="statement-"+UUID.randomUUID();mvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("username",name,"password","StatementsSecret123","phoneNumber","+1776"+String.format("%010d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%10000000000L)))))).andExpect(status().isOk());var response=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("identifier",name,"password","StatementsSecret123")))).andExpect(status().isOk()).andReturn();return "Bearer "+json.readTree(response.getResponse().getContentAsString()).get("accessToken").asText();}
 JsonNode preview(String token,String text)throws Exception{return json.readTree(mvc.perform(multipart("/api/finance/statements/preview").file(new MockMultipartFile("file","bank.csv","text/csv",text.getBytes(StandardCharsets.UTF_8))).param("account","Savings").param("dateOrder","DMY").header("Authorization",token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 JsonNode report(String token,String period,String anchor,String zone)throws Exception{return json.readTree(mvc.perform(get("/api/finance/reports").param("period",period).param("anchor",anchor).param("zone",zone).header("Authorization",token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 @Test void importIsReviewedIdempotentAndPrivateAndTransfersAreExcluded()throws Exception{String owner=member(),other=member();String text="Date,Description,Debit,Credit\n01/02/2026,Salary,,1000\n02/02/2026,Bigbasket groceries,100,\n03/02/2026,Self transfer,200,\n04/02/2026,Myntra,50,\n";var rows=preview(owner,text).get("rows");String body=json.writeValueAsString(Map.of("account","Savings","rows",rows));mvc.perform(post("/api/finance/statements/commit").header("Authorization",owner).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.imported").value(4));mvc.perform(post("/api/finance/statements/commit").header("Authorization",owner).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.duplicates").value(4));assertThat(preview(owner,text).get("rows")).allSatisfy(row->assertThat(row.get("duplicate").asBoolean()).isTrue());var report=report(owner,"QUARTER","2026-02","Asia/Kolkata");assertThat(report.get("income").decimalValue()).isEqualByComparingTo("1000");assertThat(report.get("spending").decimalValue()).isEqualByComparingTo("150");assertThat(report.get("transfers").decimalValue()).isEqualByComparingTo("200");assertThat(report.get("timeline").size()).isEqualTo(3);assertThat(report(other,"YEAR","2026-02","Asia/Kolkata").get("transactions")).isEmpty();assertThat(preview(other,text).get("rows")).allSatisfy(row->assertThat(row.get("duplicate").asBoolean()).isFalse());long id=report.get("transactions").get(0).get("id").asLong();mvc.perform(post("/api/finance/transactions/"+id+"/category").header("Authorization",other).contentType(MediaType.APPLICATION_JSON).content("{\"category\":\"OTHER\"}")).andExpect(status().isNotFound());mvc.perform(post("/api/finance/transactions/"+id+"/category").header("Authorization",owner).contentType(MediaType.APPLICATION_JSON).content("{\"category\":\"CLOTHING\"}")).andExpect(status().isOk());}
 @Test void timezoneBoundariesAreCalendarCorrect()throws Exception{String token=member();mvc.perform(post("/api/finance/transactions").header("Authorization",token).contentType(MediaType.APPLICATION_JSON).content("{\"amount\":10,\"direction\":\"EXPENSE\",\"category\":\"OTHER\",\"source\":\"MANUAL\",\"occurredAt\":\"2026-01-31T23:30:00Z\"}")).andExpect(status().isOk());assertThat(report(token,"MONTH","2026-02","Asia/Kolkata").get("spending").decimalValue()).isEqualByComparingTo("10");assertThat(report(token,"MONTH","2026-01","UTC").get("spending").decimalValue()).isEqualByComparingTo("10");assertThat(report(token,"MONTH","2026-01","Asia/Kolkata").get("spending").decimalValue()).isZero();}
 @Test void repeatedLegitimateRowsArePreservedAndBadCommitsAreAtomic()throws Exception{String token=member();var rows=(com.fasterxml.jackson.databind.node.ArrayNode)preview(token,"Date,Description,Amount,Type\n2026-02-01,Grocery,10,DR\n2026-02-01,Grocery,10,DR\n").get("rows");assertThat(rows.get(0).get("sourceKey")).isNotEqualTo(rows.get(1).get("sourceKey"));((com.fasterxml.jackson.databind.node.ObjectNode)rows.get(1)).put("amount",-1);mvc.perform(post("/api/finance/statements/commit").header("Authorization",token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("account","Savings","rows",rows)))).andExpect(status().isBadRequest());assertThat(report(token,"YEAR","2026-02","UTC").get("transactions")).isEmpty();}
 @Test void exportEscapesSpreadsheetFormulasAndReportInputsAreValidated()throws Exception{String token=member();var rows=preview(token,"Date,Description,Amount,Type\n2026-02-01,=SUM(A1),10,DR\n").get("rows");mvc.perform(post("/api/finance/statements/commit").header("Authorization",token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("account","Savings","rows",rows)))).andExpect(status().isOk());String exported=mvc.perform(get("/api/finance/reports/export").param("period","YEAR").param("anchor","2026-02").header("Authorization",token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertThat(exported).contains("\"'=SUM(A1)\"");for(String anchor:List.of("2026-13","2026-1","0000-01"))mvc.perform(get("/api/finance/reports").param("anchor",anchor).header("Authorization",token)).andExpect(status().isBadRequest());mvc.perform(get("/api/finance/reports").param("anchor","2026-02").param("zone","bogus").header("Authorization",token)).andExpect(status().isBadRequest());}
}
